referenceSolutions.javascript:
export function solve(initial, operations) {
  const history = [initial];
  let position = 0;
  return operations.map(([op, value]) => {
    if (op === "set" && history[position] !== value) {
      history.splice(position + 1);
      history.push(value);
      position++;
    } else if (op === "undo" && position > 0) position--;
    else if (op === "redo" && position + 1 < history.length) position++;
    return history[position];
  });
}

